content.text:
{
  "name": "集群任务工作器",
  "name_en": "Cluster Task Worker",
  "manufacturer": "",
  "description": "用于实验数据处理集群的非物理软件组件。它会持续轮询任务队列、获取待处理任务、执行配方型计算流程，并将结果返回到上游队列或服务。",
  "description_en": "A non-physical software component for experimental data-processing clusters. It continuously polls task queues, fetches pending jobs, executes recipe-based computation workflows, and returns results to an upstream queue or service.",
  "actions": [
    {
      "action_name": "auto-loop_forever",
      "description": "持续运行工作器主循环。",
      "description_en": "Run the worker main loop continuously."
    },
    {
      "action_name": "auto-tasksLoop",
      "description": "轮询任务队列并获取新的待计算任务。",
      "description_en": "Poll task queues and fetch new tasks for computation."
    },
    {
      "action_name": "auto-returnLoop",
      "description": "持续返回已完成任务的结果。",
      "description_en": "Continuously return results for completed tasks."
    },
    {
      "action_name": "auto-computeLoop",
      "description": "处理已入队任务，加载输入并执行配方计算。",
      "description_en": "Process queued tasks, load inputs, and execute recipe-based computations."
    }
  ],
  "tag_hints": [
    "cluster worker",
    "distributed task processing",
    "recipe execution",
    "task queue polling",
    "result return",
    "experimental data processing",
    "PYME cluster"
  ]
}

